import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ItemCarrinho, Carrinho } from './solution.mjs';

test('carrinho soma os subtotais dos itens', () => {
  const carrinho = new Carrinho();
  carrinho.adicionar(new ItemCarrinho('Caderno', 10, 2));
  carrinho.adicionar(new ItemCarrinho('Caneta', 2.5));
  assert.equal(carrinho.total(), 22.5);
  assert.equal(carrinho.quantidadeDeItens(), 2);
});

test('item calcula o subtotal com quantidade padrão 1', () => {
  const item = new ItemCarrinho('Borracha', 3, 4);
  assert.equal(item.subtotal(), 12);
  assert.equal(new ItemCarrinho('Lápis', 2).quantidade, 1);
});

test('carrinho só aceita objetos do tipo ItemCarrinho', () => {
  const carrinho = new Carrinho();
  assert.throws(() => carrinho.adicionar({ produto: 'X', preco: 1 }));
  assert.throws(() => carrinho.adicionar('Caderno'));
  carrinho.adicionar(new ItemCarrinho('Ok', 1)); // este passa
  assert.equal(carrinho.quantidadeDeItens(), 1);
});

test('validações do item recusam dados errados', () => {
  assert.throws(() => new ItemCarrinho('', 10));
  assert.throws(() => new ItemCarrinho('X', -1));
  assert.throws(() => new ItemCarrinho('X', 10, 0));
});

solutionCode:
// ItemCarrinho é uma peça: produto, preço e quantidade com subtotal.
export class ItemCarrinho {
  constructor(produto, preco, quantidade = 1) {
    if (typeof produto !== 'string' || produto.trim() === '') {
      throw new Error('produto precisa ser um texto não vazio');
    }
    if (typeof preco !== 'number' || preco < 0) {
      throw new Error('preco precisa ser um número não negativo');
    }
    if (typeof quantidade !== 'number' || quantidade < 1) {
      throw new Error('quantidade precisa ser um número maior ou igual a 1');
    }
    this.produto = produto;
    this.preco = preco;
    this.quantidade = quantidade;
  }

  subtotal() {
    return this.preco * this.quantidade;
  }
}

// Carrinho TEM itens (composição): guarda a lista e conversa pelos métodos.
export class Carrinho {
  #itens = [];

  adicionar(item) {
    // Porteiro: só entra objeto da família ItemCarrinho.
    if (!(item instanceof ItemCarrinho)) {
      throw new Error('só aceita itens do tipo ItemCarrinho');
    }
    this.#itens.push(item);
  }

  total() {
    let soma = 0;
    for (const item of this.#itens) {
      soma += item.subtotal(); // cada item calcula o seu subtotal
    }
    return soma;
  }

  quantidadeDeItens() {
    return this.#itens.length;
  }
}
